from pydantic import BaseModel, ValidationError

class Order(BaseModel):
    order_id: str
    total: float        # coerces "42.00" -> 42.0
    ship_day: str

raw = {"order_id": "A-123", "total": "42.00", "ship_day": "Tuesday"}
try:
    order = Order(**raw)          # parse + validate + coerce
    print(order.total + 1)        # 43.0
except ValidationError as e:
    print("invalid model output:", e)
